import json, urllib.request, time

def fetch(start, num=50):
    url = f"https://moviebarcode.tumblr.com/api/read/json?start={start}&num={num}"
    req = urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
    raw = urllib.request.urlopen(req, timeout=30).read().decode().strip()
    if raw.startswith('var tumblr_api_read = '):
        raw = raw[len('var tumblr_api_read = '):]
    if raw.endswith(';'):
        raw = raw[:-1]
    return json.loads(raw)

posts = []
start = 0
try:
    while start < 2164:
        d = fetch(start)
        batch = d['posts']
        posts.extend(batch)
        if len(batch) < 50: break
        start += 50
        time.sleep(0.1)
except Exception as e:
    print("err at", start, repr(e)[:100])

print("total posts fetched:", len(posts))
json.dump(posts, open('mb_posts.json','w'))
EOF", "timeout": 600000}

